(function(){'use strict';const get=id=>document.getElementById(id),en=()=>document.documentElement.lang==='en';let scenario=[],lastBudget=null,lastSimulation=null;const money=(n,c)=>formatMoney(n,c||(scenario.length?scenario[0].currency:currency));const budgetLabels={income:'Ingresos',essential:'Gastos esenciales',fixed:'Otros gastos fijos',variable:'Otros gastos variables',minimums:'Pagos mínimos',extra:'Abono adicional propuesto'};get('budget-fields').innerHTML=Object.entries(budgetLabels).map(([k,v])=>`<div class="field"><label for="budget-${k}">${v}</label><input type="number" min="0" step="0.01" id="budget-${k}" value="0"></div>`).join('');
const budgetKey='deudas-budget-v1';let budgetRaw=null,budgetReadFailed=false,budgetSaveState='';try{budgetRaw=localStorage.getItem(budgetKey);if(budgetRaw!==null){let saved=JSON.parse(budgetRaw);for(const k of Object.keys(budgetLabels)){if(typeof saved[k]!=='number'||!Number.isFinite(saved[k])||saved[k]<0)throw Error();get('budget-'+k).value=String(saved[k])}}}catch(_){budgetReadFailed=true;get('budget-output').textContent='El presupuesto guardado requiere revisión. No se reemplazará.'}
function saveBudget(v){if(budgetReadFailed)return 'requiresReview';try{if(localStorage.getItem(budgetKey)!==budgetRaw){budgetReadFailed=true;return 'conflict'}let serialized=JSON.stringify(v);(localStorage.getItem('nando-restore-journal-v1')!==null?(()=>{throw Error('Hay una recuperación pendiente; no se guardó ningún cambio.')})():localStorage.setItem(budgetKey,serialized));if(localStorage.getItem(budgetKey)!==serialized)throw Error();budgetRaw=serialized;return 'saved'}catch(_){return 'failed'}}
function budgetSuffix(){const map={requiresReview:['El presupuesto guardado no se modificó porque requiere revisión.','The saved budget was not changed because it needs review.'],conflict:['No se guardó: el presupuesto cambió en otra ventana.','Not saved: the budget changed in another window.'],saved:['Presupuesto guardado en este dispositivo.','Budget saved on this device.'],failed:['No se pudo guardar el presupuesto en este dispositivo.','Could not save the budget on this device.']};return map[budgetSaveState]?' '+map[budgetSaveState][en()?1:0]:''}
function outputBudget(b){return en()?`Available after expenses and minimums: ${money(b.availableAfterMinimums)}. ${b.exceedsCapacity?'The proposed extra payment exceeds capacity by '+money(b.shortfall)+'.':'The proposed extra payment is within the calculated capacity.'}`:`Disponible después de gastos y mínimos: ${money(b.availableAfterMinimums)}. ${b.exceedsCapacity?'El abono propuesto supera la capacidad en '+money(b.shortfall)+'.':'El abono propuesto está dentro de la capacidad calculada.'}`}
function outputStrategy(r,label){if(r.status==='insufficient_minimums')return en()?`${label}: the monthly payment is below the required minimums.`:`${label}: el pago mensual no alcanza para los mínimos.`;if(r.status!=='paid')return en()?`${label}: not paid off within the projection horizon.`:`${label}: no se cancela dentro del horizonte de cálculo.`;const names=r.debts.slice().filter(d=>d.payoffDate).sort((a,b)=>a.payoffDate.localeCompare(b.payoffDate)).map(d=>d.name).join(', ');return en()?`${label}: ${r.months} months, estimated interest ${money(r.totalInterest)}, date ${r.payoffDate}. Payoff order: ${names}.`:`${label}: ${r.months} meses, interés estimado ${money(r.totalInterest)}, fecha ${r.payoffDate}. Orden de cancelación: ${names}.`}
function renderSimulation(){if(!lastSimulation)return;get('sim-output').dataset.localizedOutput='true';get('sim-output').textContent=outputStrategy(lastSimulation.snowball,en()?'Snowball':'Bola de nieve')+' '+outputStrategy(lastSimulation.avalanche,en()?'Avalanche':'Avalancha');renderVisual()}
function renderVisual(){const output=get('sim-output');if(typeof output.after!=='function')return;let box=get('sim-visual');if(!box){box=document.createElement('div');box.id='sim-visual';output.after(box)}let snow=lastSimulation.snowball,ava=lastSimulation.avalanche;if(snow.status!=='paid'||ava.status!=='paid'){box.replaceChildren();return}const lang=en(),labels=lang?['Projected interest','Snowball','Avalanche','View monthly amortization','Month','Payment','Minimums','Extra','Interest','Remaining']:['Intereses proyectados','Bola de nieve','Avalancha','Ver amortización mensual','Mes','Pago','Mínimos','Extra','Interés','Saldo pendiente'];const max=Math.max(snow.totalInterest,ava.totalInterest);const bar=(name,r)=>`<div style="margin:.55rem 0"><div style="display:flex;justify-content:space-between;gap:1rem"><strong>${name}</strong><span>${money(r.totalInterest)}</span></div><div style="height:.7rem;background:#e4ece6;border-radius:1rem;overflow:hidden" role="img" aria-label="${name}: ${money(r.totalInterest)}"><div style="height:100%;width:${max?Math.round(100*r.totalInterest/max):0}%;background:#1b684d"></div></div></div>`;const table=(name,r)=>`<h4>${name}</h4><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;text-align:right;font-size:.9rem"><thead><tr>${labels.slice(4).map(x=>`<th style="padding:.4rem">${x}</th>`).join('')}</tr></thead><tbody>${r.periods.map(p=>`<tr><td>${p.date}</td><td>${money(p.payment)}</td><td>${money(p.minimums)}</td><td>${money(p.extra)}</td><td>${money(p.interest)}</td><td>${money(p.balance)}</td></tr>`).join('')}</tbody></table></div>`;box.innerHTML=`<h3>${labels[0]}</h3>${bar(labels[1],snow)}${bar(labels[2],ava)}<details><summary>${labels[3]}</summary>${table(labels[1],snow)}${table(labels[2],ava)}</details>`}
// Hypothetical budget changes never alter saved values or recorded debts.
function initScenario(){let output=get('budget-output');if(typeof output.after!=='function')return;let box=document.createElement('div');box.id='budget-scenario';box.innerHTML='<h4 id="scenario-heading"></h4><p id="scenario-note"></p><div class="formgrid"><div class="field"><label for="scenario-income" id="scenario-income-label"></label><input id="scenario-income" type="number" min="0" step="0.01" value="0"></div><div class="field"><label for="scenario-expense" id="scenario-expense-label"></label><input id="scenario-expense" type="number" min="0" step="0.01" value="0"></div></div><p id="scenario-result" aria-live="polite"></p>';output.after(box);get('scenario-income').oninput=renderScenario;get('scenario-expense').oninput=renderScenario;renderScenario()}
function renderScenario(){if(!get('budget-scenario'))return;const lang=en();get('scenario-heading').textContent=lang?'Compare a monthly scenario':'Comparar un escenario mensual';get('scenario-note').textContent=lang?'This simulation does not change your saved budget.':'Esta simulación no modifica tu presupuesto guardado.';get('scenario-income-label').textContent=lang?'Additional monthly income':'Ingresos mensuales adicionales';get('scenario-expense-label').textContent=lang?'Additional monthly expenses':'Gastos mensuales adicionales';const income=Number(get('scenario-income').value),expense=Number(get('scenario-expense').value),out=get('scenario-result');if(!lastBudget||!Number.isFinite(income)||income<0||!Number.isFinite(expense)||expense<0){out.textContent=lang?'Complete a valid budget and nonnegative scenario amounts.':'Completa un presupuesto válido y valores no negativos.';return}let baseline=lastBudget.availableAfterMinimums-lastBudget.proposedExtra,alternative=baseline+income-expense;out.textContent=lang?`Cash flow after the proposed extra payment: current ${money(baseline)}; scenario ${money(alternative)}.`:`Flujo después del abono adicional propuesto: actual ${money(baseline)}; escenario ${money(alternative)}.`}
function calculateBudget(){try{let v={};for(const k of Object.keys(budgetLabels)){let el=get('budget-'+k);if(el.value==='')throw Error('Completa todos los valores.');v[k]=Number(el.value)}lastBudget=DebtEngine.budget(v);budgetSaveState=saveBudget(v);get('budget-output').dataset.localizedOutput='true';get('budget-output').textContent=outputBudget(lastBudget)+budgetSuffix();renderScenario()}catch(e){lastBudget=null;delete get('budget-output').dataset.localizedOutput;get('budget-output').textContent=e.message;renderScenario()}};get('budget-calc').onclick=calculateBudget;for(const k of Object.keys(budgetLabels))get('budget-'+k).oninput=calculateBudget;const today=new Date();get('sim-date').value=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');get('sim-load').onclick=()=>{scenario=debts.filter(d=>d.currency===currency&&d.balance>0).map(d=>({id:d.id,name:d.name,currency:d.currency,balance:d.balance}));lastSimulation=null;get('sim-output').textContent='';let box=get('simulation-rows');box.replaceChildren();get('sim-visual')?.replaceChildren();if(!scenario.length){box.textContent='No hay deudas con saldo en esta moneda.';return}scenario.forEach((d,i)=>{let row=document.createElement('div');row.className='card';let title=document.createElement('strong');title.textContent=d.name+' — '+money(d.balance,d.currency);row.append(title);let inputs=document.createElement('div');inputs.className='formgrid';inputs.innerHTML=`<div class="field"><label for="min-${i}">Pago mínimo mensual</label><input id="min-${i}" type="number" min="0" step="0.01"></div><div class="field"><label for="rate-${i}">Tasa anual confirmada (%)</label><input id="rate-${i}" type="number" min="0" step="0.01"></div><div class="field"><label for="kind-${i}">Tipo de tasa</label><select id="kind-${i}"><option value="">Seleccionar</option><option value="APR">APR nominal</option><option value="EA">Efectiva anual (E.A.)</option></select></div>`;row.append(inputs);box.append(row)})};get('sim-calc').onclick=()=>{try{if(!scenario.length)throw Error('Carga tus deudas primero.');let current=debts.filter(d=>d.currency===currency&&d.balance>0);if(current.length!==scenario.length||current.some((d,i)=>d.id!==scenario[i].id||d.balance!==scenario[i].balance||d.currency!==scenario[i].currency))throw Error('Tus deudas cambiaron. Vuelve a cargarlas antes de comparar.');let v=scenario.map((d,i)=>{let mn=get('min-'+i),rate=get('rate-'+i),kind=get('kind-'+i);if(!mn.value||!rate.value||!kind.value)throw Error('Completa mínimo, tasa y tipo de tasa para cada deuda.');return {...d,minimum:Number(mn.value),rate:Number(rate.value),rateType:kind.value}});let amount=get('sim-budget').value,date=get('sim-date').value;if(!amount||!date)throw Error('Completa el pago mensual y la fecha de inicio.');lastSimulation=DebtEngine.compare(v,Number(amount),date);renderSimulation()}catch(e){lastSimulation=null;get('sim-visual')?.replaceChildren();delete get('sim-output').dataset.localizedOutput;get('sim-output').textContent=e.message}};
initScenario();document.addEventListener('deudas:languagechange',()=>{if(lastBudget)get('budget-output').textContent=outputBudget(lastBudget)+budgetSuffix();renderScenario();renderSimulation()});})();
